--muted);line-height:1.6;margin:0 0 22px}.setting{margin:0 0 23px}.setting-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;gap:8px}.setting label{font-size:12px}.value-field{display:flex;align-items:center;gap:5px;font-size:10px;color:var(--muted)}input[type=number]{width:47px;text-align:right;border:1px solid var(--line);border-radius:4px;padding:4px;background:var(--paper);color:var(--ink);font:12px ui-monospace,monospace;appearance:textfield}input::-webkit-inner-spin-button{appearance:none}input[type=range]{width:100%;margin:0;appearance:none;height:3px;background:var(--line);border-radius:3px;accent-color:var(--green);cursor:pointer;display:block}input[type=range]::-webkit-slider-thumb{appearance:none;background:var(--green);width:12px;height:12px;border:2px solid var(--white);border-radius:50%;box-shadow:0 0 0 1px var(--green)}input[type=range]::-moz-range-thumb{background:var(--green);width:9px;height:9px;border:2px solid white;border-radius:50%}.range-labels{display:flex;justify-content:space-between;font-size:9px;color:var(--muted);margin-top:9px}.wall-summary{border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:14px 0;display:flex;justify-content:space-between;font-size:11px;margin:2px 0 17px}.wall-summary strong{font-weight:500}.defaults{min-height:30px;padding:0;border:0;color:var(--green);font-size:11px;background:none}.defaults:hover{background:none;text-decoration:underline}.pending{font-size:10px;color:var(--green);line-height:1.5;min-height:29px;margin:7px 0 0}.lower{display:grid;grid-template-columns:1.15fr 1fr;gap:32px;margin-top:25px}.chart-section{border:1px solid var(--line);border-radius:7px;background:var(--white);padding:16px 18px}.chart-head{display:flex;justify-content:space-between;font-size:11px}.chart-head span:last-child{font-size:10px;color:var(--muted)}#plot{width:100%;height:67px;display:block;margin-top:10px}.method{padding:4px 0}.method h3{font-size:12px;font-weight:500;margin:0 0 11px;display:flex;align-items:center;gap:8px}.method p{font-size:11px;line-height:1.8;color:var(--muted);max-width:520px;margin:0}.constants{display:flex;flex-wrap:wrap;gap:7px 17px;margin-top:13px;font-size:10px;color:var(--muted)}details{margin-top:10px;font-size:11px;color:var(--muted)}summary{cursor:pointer}details p{margin-top:7px!important}footer{display:flex;justify-content:space-between;margin-top:24px;padding-top:17px;border-top:1px solid var(--line);font-size:9px;letter-spacing:.6px;color:var(--muted)}.keyboard{font-size:10px}kbd{font:10px ui-monospace,monospace;border:1px solid var(--line);border-radius:3px;padding:3px 5px;margin-right:4px}.settings-toggle{font-size:11px;display:flex;gap:8px;align-items:center}.experiment.hide-settings{grid-template-columns:1fr}.hide-settings .inspector{display:none}@media(min-width:1500px){.viewport{height:550px}.workspace{padding-top:40px}.setting{margin-bottom:29px}}@media(max-width:900px){header{padding:0 20px}.workspace{padding:25px 20px}.experiment{grid-template-columns:minmax(0,1fr) 240px}.inspector{padding:20px 16px}.metric{padding:0 13px}.transport{padding:15px 13px}.transport-note{display:none}.metric-number{font-size:23px}.header-note>span:first-child{display:none}.view-top{left:15px;right:15px}.lower{gap:22px}}@media(max-width:680px){header{height:67px}.header-note{font-size:10px}.workspace{padding:24px 14px}.intro h2{font-size:24px}.intro p{font-size:11px;max-width:225px;line-height:1.5}.experiment{grid-template-columns:1fr}.viewport{height:350px}.inspector{border-left:0;border-top:1px solid var(--line);display:grid;grid-template-columns:1fr 1fr;column-gap:22px}.panel-heading,.panel-subtitle,.wall-summary,.pending{grid-column:1/-1}.panel-subtitle{margin-bottom:20px}.setting{margin-bottom:20px}.lower{grid-template-columns:1fr;gap:19px}.metric{padding:0 11px}.metric-number{font-size:21px}.metric-label{font-size:9px}.metric-hint{font-size:8px}.view-bottom{left:15px;right:15px}.legend{gap:10px}.viewp