+<body>
+<header><div class="brand"><svg viewBox="0 0 30 30" fill="none" aria-hidden="true"><path d="M3 5h10v9H3zm14 0h10v9H17zM3 18h10v9H3zm14 0h10v9H17z" stroke="currentColor" stroke-width="1.5"/><path d="m11 3 7 25M3 16l24-3" stroke="var(--green)" stroke-width="2"/></svg><h1>GPT-6 Astra</h1></div><div class="header-note mono"><span>MECHANICS / EXPERIMENT LAB</span><span class="online"><i class="dot"></i> LOCAL SIMULATION</span></div></header>
+<main class="workspace">
+<section class="intro"><div><div class="eyebrow mono">EXPERIMENT 001</div><h2>When momentum meets masonry.</h2><p>A repeatable crash test. Every brick is a body. Every impact is physics.</p></div><button class="settings-toggle" id="settingsToggle" aria-expanded="true" aria-controls="settings">☷ <span>Settings</span></button></section>
+<section class="experiment" id="experiment" aria-label="Crash experiment">
+<div class="view"><div class="viewport"><canvas id="scene" aria-label="Side-view car and individually simulated brick wall">A car crash experiment. Use Test to launch the car and Reset to restore the scene.</canvas><div class="view-top"><div class="status" id="status" role="status"><i class="dot"></i><span id="statusText">READY TO TEST</span></div><span class="viewport-id mono">SIDE ELEVATION &nbsp; / &nbsp; RIG 01</span></div><div class="view-bottom mono"><div class="legend"><span><i class="swatch"></i>VEHICLE</span><span><i class="swatch brick"></i>MASONRY</span></div><span id="scaleLabel">1 m ━━━━━</span></div></div>
+<div class="transport"><div class="transport-buttons"><button class="test" id="test"><svg viewBox="0 0 12 12" aria-hidden="true"><path d="m2 1 9 5-9 5z" fill="currentColor"/></svg>Test</button><button class="quiet" id="reset">↺ &nbsp; Reset</button><button class="quiet" id="pause" disabled aria-label="Pause simulation">Ⅱ</button><button class="rate mono" id="rate" title="Change playback speed" aria-label="Playback speed, 1 times">1×</button></div><span class="transport-note mono" id="runNote">FIXED STEP · DETERMINISTIC</span></div>
+<div class="metrics"><div class="metric"><div class="metric-label">Car speed</div><div class="metric-number mono"><span id="speedMetric">0.0</span><small>m/s</small></div><div class="metric-hint" id="speedHint">22 m/s target</div></div><div class="metric"><div class="metric-label">Elapsed time</div><div class="metric-number mono"><span id="timeMetric">0.00</span><small>s</small></div><div class="metric-hint">Simulation time</div></div><div class="metric"><div class="metric-label">Moving bricks</div><div class="metric-number mono"><span id="movingMetric">0</span><small id="brickTotal">/ 192</small></div><div class="metric-hint">Translation + rotation</div></div><div class="metric"><div class="metric-label">Vehicle energy</div><div class="metric-number mono"><span id="energyMetric">0.0</span><small>kJ</small></div><div class="metric-hint">Current kinetic energy</div></div></div></div>
+<aside class="inspector" id="settings"><div class="panel-heading"><h3>Test parameters</h3><svg viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="M2 4h12M2 8h12M2 12h12" stroke="currentColor"/><path d="M5 2v4m6 0v4m-5 0v4" stroke="currentColor" stroke-width="2"/></svg></div><p class="panel-subtitle">Change the setup. Observe the difference.</p><div id="settingsFields" style="display:contents"></div><div class="wall-summary"><span id="wallCount">192 bricks</span><strong class="mono" id="wallMass">480 kg total</strong></div><button class="defaults" id="defaults">↶ &nbsp; Restore defaults</button><p class="pending" id="pending">Parameters are applied at the start of each test.</p></aside>
+</section>
+<section class="lower"><div class="chart-section"><div class="chart-head"><span>Velocity over time</span><span class="mono" id="plotCaption">0.00 s &nbsp; / &nbsp; 0.0 m/s</span></div><canvas id="plot" aria-label="Car velocity over simulation time"></canvas></div><div class="method"><h3><i class="dot"></i>Built on contact, not choreography.</h3><p>Gravity, rotational inertia, friction, and momentum transfer. A fixed-step rigid-body solver makes the same setup repeatable, down to the final brick.</p><div class="constants mono"><span>g 9.81 m/s²</span><span>μ brick 0.72</span><span>μ ground 0.85</span><span>e 0.18</span></div><details><summary>Model &amp; fixed specifications</summary><p>1,250 kg vehicle · 4.2 × 1.45 m collision envelope. Each brick is 0.50 × 0.24 m. World scale: 80 px/m, with responsive camera zoom. Depth layers occupy parallel 2D planes: each layer has brick-to-brick contact and all layers exchange impulses with the same vehicle. No mortar or artificial break animation. The launch rig accelerates to the chosen speed; propulsion disengages on first wall contact. This is an illustrative rigid-body experiment, not a structural safety model.</p></details></div></section>
+<footer class="mono"><span>RIGID BODY DYNAMICS &nbsp; / &nbsp; OFFLINE READY</span><span class="keyboard"><kbd>SPACE</kbd> Test / pause &nbsp; <kbd>R</kbd> Reset</span><span>SI UNITS · 2D LAYERED MODEL</span></footer>
+</main>
+<script>
+'"'use strict';
+const DEFAULTS=Object.freeze({speed:22,columns:12,rows:8,layers:2,mass:2.5});
+const CONSTANTS=Object.freeze({gravity:9.81,brickWidth:.5,brickHeight:.24,brickFriction:.72,restitution:.18,carMass:1250,carWidth:4.2,carHeight:1.45,groundFriction:.85,scale:80});
+const FIELD_DEFINITIONS=[['speed','Car speed',5,45,1,'m/s'],['columns','Wall columns',4,24,1,''],['rows','Wall rows',3,16,1,''],['layers','Depth layers',1,5,1,''],['mass','Brick mass',.5,12,.5,'kg']];
+const element=id=>document.getElementById(id);
+let settings={...DEFAULTS},active={...DEFAULTS};
+const canvas=element('scene'),context=canvas.getContext('2d'),plot=element('plot'),plotContext=plot.getContext('2d');
+const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
+const clamp=(value,min,max)=>Math.max(min,Math.min(max,value));
+const dot=(first,second)=>first.x*second.x+first.y*second.y;
+const cross=(first,second)=>first.x*second.y-first.y*second.x;
+const add=(first,second)=>({x:first.x+second.x,y:first.y+second.y});
+const subtract=(first,second)=>({x:first.x-second.x,y:first.y-second.y});
+const multiply=(vector,factor)=>({x:vector.x*factor,y:vector.y*factor});
+let nextId=0;
+class RigidBody{
+ constructor(x,y,width,height,mass,layer){this.id=nextId++;this.position={x,y};this.initial={x,y};this.velocity={x:0,y:0};this.angle=0;this.angularVelocity=0;this.halfWidth=width/2;this.halfHeight=height/2;this.mass=mass;this.inverseMass=mass?1/mass:0;this.inverseInertia=mass?12/(mass*(width*width+height*height)):0;this.layer=layer;this.friction=CONSTANTS.brickFriction;this.restitution=CONSTANTS.restitution;this.updateGeometry();}
+ updateGeometry(){const cosine=Math.cos(this.angle),sine=Math.sin(this.angle);this.axes=[{x:cosine,y:sine},{x:-sine,y:cosine}];const horizontal=multiply(this.axes[0],this.halfWidth),vertical=multiply(this.axes[1],this.halfHeight);this.vertices=[subtract(subtract(this.position,horizontal),vertical),subtract(add(this.position,horizontal),vertical),add(add(this.position,horizontal),vertical),add(subtract(this.position,horizontal),vertical)];const extentX=Math.abs(horizontal.x)+Math.abs(vertical.x),extentY=Math.abs(horizontal.y)+Math.abs(vertical.y);this.bounds={minX:this.position.x-extentX-.003,maxX:this.position.x+extentX+.003,minY:this.position.y-extentY-.003,maxY:this.position.y+extentY+.003};}
+}
+function projectedRadius(body,axis){return Math.abs(dot(body.axes[0],axis))*body.halfWidth+Math.abs(dot(body.axes[1],axis))*body.halfHeight;}
+function clipSegment(start,end,center,tangent,extent){
+ const startProjection=dot(subtract(start,center),tangent),difference=dot(subtract(end,start),tangent);
+ if(Math.abs(difference)<1e-9)return Math.abs(startProjection)<=extent?[start,end]:[];
+ const lower=(-extent-startProjection)/difference,upper=(extent-startProjection)/difference;
+ const minimum=Math.max(0,Math.min(lower,upper)),maximum=Math.min(1,Math.max(lower,upper));
+ if(minimum>maximum)return [];
+ const delta=subtract(end,start);return [add(start,multiply(delta,minimum)),add(start,multiply(delta,maximum))];
+}
+function collideBoxes(first,second){
+ const delta=subtract(second.position,first.position);let overlap=Infinity,normal,reference,axisIndex;
+ for(const body of [first,second])for(let index=0;index<2;index++){
+  const axis=body.axes[index],distance=dot(delta,axis),depth=projectedRadius(first,axis)+projectedRadius(second,axis)-Math.abs(distance);
+  if(depth<-.002)return null;
+  if(depth<overlap){overlap=depth;normal=multiply(axis,distance>=0?1:-1);reference=body;axisIndex=index;}
+ }
+ const incident=reference===first?second:first,referenceNormal=reference===first?normal:multiply(normal,-1);
+ const referenceExtent=axisIndex===0?reference.halfWidth:reference.halfHeight;
+ const tangent=reference.axes[1-axisIndex],tangentExtent=axisIndex===0?reference.halfHeight:reference.halfWidth;
+ const faceCenter=add(reference.position,multiply(referenceNormal,referenceExtent));
+ const incidentAxis=Math.abs(dot(incident.axes[0],referenceNormal))>Math.abs(dot(incident.axes[1],referenceNormal))?0:1;
+ const incidentNormal=multiply(incident.axes[incidentAxis],dot(incident.axes[incidentAxis],referenceNormal)>0?-1:1);
+ const incidentCenter=add(incident.position,multiply(incidentNormal,incidentAxis===0?incident.halfWidth:incident.halfHeight));
+ const incidentTangent=multiply(incident.axes[1-incidentAxis],incidentAxis===0?incident.halfHeight:incident.halfWidth);
+ const clipped=clipSegment(subtract(incidentCenter,incidentTangent),add(incidentCenter,incidentTangent),faceCenter,tangent,tangentExtent);
+ const points=clipped.map(point=>({position:point,depth:-dot(subtract(point,faceCenter),referenceNormal)})).filter(point=>point.depth>=-.002);
+ if("'!points.length)return null;
+ return {first,second,normal,points,key:first.id+'"':'+second.id};
+}
+let bodies=[],bricks=[],car,ground,contactCache=new Map(),time=0,step=1/240,running=false,paused=false,hasRun=false,impacted=false,impactTime=null,movingCount=0,quietTime=0,history=[],dust=[],speedFactor=1,accumulator=0,lastFrame=0,viewWidth=0,viewHeight=0,pixelRatio=1,zoom=1,cameraLeft=0,groundScreen=0,shake=0;
+const WALL_X=12,START_X=3,LAUNCH_ACCEL_DISTANCE=WALL_X-START_X-CONSTANTS.carWidth/2-.6;
+function findContacts(){
+ const contacts=[],grid=new Map(),seen=new Set();
+ for(const body of bodies){
+  if(body.bounds.maxY>-.002){const floorPoints=body.vertices.filter(vertex=>vertex.y>=-.002).sort((first,second)=>second.y-first.y).slice(0,2).map(vertex=>({position:{x:vertex.x,y:0},depth:vertex.y}));if(floorPoints.length)contacts.push({first:body,second:ground,normal:{x:0,y:1},points:floorPoints,key:body.id+':floor'});}
+  const bounds=body.bounds;
+  for(let column=Math.floor(bounds.minX);column<=Math.floor(bounds.maxX);column++)for(let row=Math.floor(bounds.minY);row<=Math.floor(bounds.maxY);row++){
+   const key=column+','+row;let bucket=grid.get(key);if("'!bucket){bucket=[];grid.set(key,bucket);}
+   for(const other of bucket){
+    if(body.layer!==other.layer&&body!==car&&other!==car)continue;
+    const pairKey=other.id*bodies.length+body.id;if(seen.has(pairKey))continue;seen.add(pairKey);
+    if(bounds.minX>other.bounds.maxX||bounds.maxX<other.bounds.minX||bounds.minY>other.bounds.maxY||bounds.maxY<other.bounds.minY)continue;
+    const manifold=collideBoxes(other,body);if(manifold)contacts.push(manifold);
+   }
+   bucket.push(body);
+  }
+ }
+ return contacts;
+}
+function contactVelocity(body,offset){return {x:body.velocity.x-body.angularVelocity*offset.y,y:body.velocity.y+body.angularVelocity*offset.x};}
+function applyImpulse(body,impulse,offset,direction){if(!body.inverseMass)return;body.velocity.x+=impulse.x*body.inverseMass*direction;body.velocity.y+=impulse.y*body.inverseMass*direction;body.angularVelocity+=cross(offset,impulse)*body.inverseInertia*direction;}
+function prepareContacts(manifolds){
+ const constraints=[];
+ for(const manifold of manifolds){
+  const {first,second,normal}=manifold,tangent={x:-normal.y,y:normal.x},previous=contactCache.get(manifold.key)||[];
+  if(!impacted&&(first===car||second===car)&&second!==ground){impacted=true;impactTime=time;makeDust();}
+  for(const point of manifold.points){
+   const offsetFirst=subtract(point.position,first.position),offsetSecond=subtract(point.position,second.position);
+   const normalFirst=cross(offsetFirst,normal),normalSecond=cross(offsetSecond,normal),tangentFirst=cross(offsetFirst,tangent),tangentSecond=cross(offsetSecond,tangent);
+   const normalMass=1/(first.inverseMass+second.inverseMass+normalFirst*normalFirst*first.inverseInertia+normalSecond*normalSecond*second.inverseInertia);
+   const tangentMass=1/(first.inverseMass+second.inverseMass+tangentFirst*tangentFirst*first.inverseInertia+tangentSecond*tangentSecond*second.inverseInertia);
+   const relative=subtract(contactVelocity(second,offsetSecond),contactVelocity(first,offsetFirst)),normalSpeed=dot(relative,normal);
+   const cached=previous.find(saved=>Math.hypot(saved.position.x-point.position.x,saved.position.y-point.position.y)<.09);
+   const constraint={...point,first,second,normal,tangent,offsetFirst,offsetSecond,normalMass,tangentMass,key:manifold.key,normalImpulse:cached?cached.normalImpulse*.85:0,tangentImpulse:cached?cached.tangentImpulse*.85:0,friction:Math.sqrt(first.friction*second.friction),target:Math.max(Math.min(1.5,.18*Math.max(0,point.depth-.0015)/step),normalSpeed<-.8?-Math.min(first.restitution,second.restitution)*normalSpeed:0)};
+   constraints.push(constraint);
+  }
+ }
+ for(const constraint of constraints){const impulse=add(multiply(constraint.normal,constraint.normalImpulse),multiply(constraint.tangent,constraint.tangentImpulse));applyImpulse(constraint.first,impulse,constraint.offsetFirst,-1);applyImpulse(constraint.second,impulse,constraint.offsetSecond,1);}
+ return constraints;
+}
+function solveContacts(constraints){
+ for(let iteration=0;iteration<16;iteration++)for(const constraint of constraints){
+  const {first,second,offsetFirst,offsetSecond,normal,tangent}=constraint;
+  let relative=subtract(contactVelocity(second,offsetSecond),contactVelocity(first,offsetFirst));
